import { formatReportRange } from "./report-periods.js";
const e=value=>String(value??"").replace(/[&<>\"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const number=value=>Number.isFinite(Number(value))?Number(value):null;
const metric=(label,value)=>value==null?"":`<article class="card report-metric"><span>${e(label)}</span><strong>${e(value)}</strong></article>`;
const list=(rows,empty)=>rows?.length?`<ul class="clean-list">${rows.map(row=>`<li>${e(row.label??row.topic_key??row)}${number(row.percent??row.accuracy_percent)!=null?` · %${number(row.percent??row.accuracy_percent)}`:""}</li>`).join("")}</ul>`:`<p class="meta">${e(empty)}</p>`;

export function learningReportView({children=[],selectedChildId,periodType,period,payload,history=[],weeklyReports=[],monthlyReports=[],weeklyEmailEnabled=true,monthlyEmailEnabled=true,loading=false,error=""}){
  const summary=payload?.summary||{},vocab=payload?.vocabulary||{},hasData=Boolean(payload?.has_data),child=children.find(row=>String(row.id)===String(selectedChildId));
  const weekly=weeklyReports[0],wm=weekly?.metrics||{};
  const weeklyCard=weekly?`<article class="card"><p class="eyebrow">HAFTALIK GELİŞİM</p><h2>${e(weekly.child_name)}</h2><p>${weekly.status==="insufficient_data"?"Bu hafta için henüz yeterli veri oluşmadı":"Haftalık rapor hazır"}</p><div class="report-metrics">${metric("Aktif gün",number(wm.active_days))}${metric("Tamamlanan ders",number(wm.lessons_completed))}${metric("Soru performansı",number(wm.accuracy_percent)==null?"Ölçülebilir soru etkinliği yok":`%${number(wm.accuracy_percent)}`)}${metric("Oyun / hikâye",`${number(wm.games_completed)||0} / ${number(wm.stories_completed)||0}`)}</div><h3>Güçlü alanlar</h3>${list(weekly.strengths,"Henüz güvenilir güçlü alan verisi yok.")}<h3>Tekrar önerileri</h3>${list(weekly.practice_recommendations,"Biraz daha pratik önerilir.")}</article>`:`<article class="card"><p class="eyebrow">HAFTALIK GELİŞİM</p><h2>Rapor hazırlanıyor</h2><p>Bu hafta için henüz oluşturulmuş rapor bulunmuyor.</p></article>`;
  const monthly=monthlyReports[0],mm=monthly?.metrics||{},monthlyCard=monthly?`<article class="card"><p class="eyebrow">AYLIK GELİŞİM</p><h2>${e(monthly.child_name)}</h2><p>${monthly.status==="insufficient_data"?"Bu ay için henüz yeterli veri oluşmadı":"Aylık rapor hazır"}</p><div class="report-metrics">${metric("Aktif hafta / gün",`${number(mm.active_weeks)||0} / ${number(mm.active_days)||0}`)}${metric("Tamamlanan ders",number(mm.lessons_completed))}${metric("Cevaplanan soru",number(mm.questions_answered))}${metric("Doğruluk",number(mm.accuracy_percent)==null?"Yeterli soru verisi yok":`%${number(mm.accuracy_percent)}`)}${metric("Oyun / hikâye",`${number(mm.games_completed)||0} / ${number(mm.stories_completed)||0}`)}</div><h3>Çalışılan konular</h3>${list(monthly.topics_studied,"Henüz konu verisi yok.")}<h3>Gelişim gösterilen konular</h3>${list(monthly.improved_topics,"İki ayda da yeterli karşılaştırma verisi yok.")}<h3>Tekrar önerileri</h3>${list(monthly.review_topics,"Yeterli konu verisi yok.")}</article>`:`<article class="card"><p class="eyebrow">AYLIK GELİŞİM</p><h2>Rapor hazırlanıyor</h2><p>Henüz oluşturulmuş aylık rapor bulunmuyor.</p></article>`;
  return `<section class="learning-report-center" data-learning-report-center><div class="page-head"><div><p class="eyebrow">VELİ PANELİ</p><h1>Gelişim Raporları</h1><p class="lead">Doğrulanmış öğrenme verilerinden güvenli gelişim özeti.</p></div><div class="button-row"><button class="button secondary" data-action="print-learning-report">Raporu Yazdır</button><button class="button secondary" data-route="parent">Veli paneline dön</button></div></div>
  <section class="card report-controls"><label>Çocuk<select data-report-child>${children.map(row=>`<option value="${e(row.id)}" ${String(row.id)===String(selectedChildId)?"selected":""}>${e(row.name)}</option>`).join("")}</select></label><div class="report-tabs"><button class="button ${periodType==="weekly"?"primary":"secondary"}" data-report-period="weekly">Haftalık</button><button class="button ${periodType==="monthly"?"primary":"secondary"}" data-report-period="monthly">Aylık</button></div></section>
  <section class="report-history"><div class="section-title-row"><div><h2>Haftalık Gelişim</h2><p class="meta">Yalnız tarihçeli gerçek etkinliklerden hazırlanır.</p></div><label><input type="checkbox" data-weekly-email-preference ${weeklyEmailEnabled?"checked":""}> Haftalık raporu e-postayla al</label></div>${weeklyCard}</section>
  <section class="report-history"><div class="section-title-row"><div><h2>Aylık Gelişim</h2><p class="meta">Takvim ayı boyunca oluşan gerçek öğrenme kayıtlarından hazırlanır.</p></div><label><input type="checkbox" data-monthly-email-preference ${monthlyEmailEnabled?"checked":""}> Aylık raporu e-postayla al</label></div>${monthlyCard}</section>
  ${loading?`<article class="card" role="status">Rapor yükleniyor…</article>`:error?`<article class="card feedback incorrect" role="alert">${e(error)}</article>`:`<article class="report-print-area"><header class="card report-title"><p class="eyebrow">${periodType==="weekly"?"HAFTALIK":"AYLIK"} ÖN İZLEME</p><h2>${e(child?.name||"Öğrenci")}</h2><p>${e(formatReportRange(period))}</p></header>${hasData?`<div class="report-metrics">${metric("Tamamlanan ders",number(summary.completed_lessons))}${metric("Başlanan ders",number(summary.started_lessons))}${metric("Toplam cevap",number(summary.total_answers))}${metric("Başarı",number(summary.accuracy_percent)==null?null:`%${number(summary.accuracy_percent)}`)}</div>`:`<article class="card report-empty"><h2>Henüz yeterli veri yok</h2><p>${e(payload?.parent_comment||"Bu dönemde rapor oluşturacak yeterli çalışma kaydı bulunmuyor.")}</p></article>`}<div class="report-sections"><article class="card"><h2>Güçlü alanlar</h2>${list(payload?.topics?.strong,"Bu dönem için güvenilir konu verisi yok.")}</article><article class="card"><h2>Tekrar edilmesi gereken alanlar</h2>${list(payload?.topics?.review,"Bu dönem için güvenilir tekrar alanı yok.")}</article><article class="card"><h2>Kelime gelişimi</h2><p>Görülen: ${number(vocab.seen)??"—"} · Öğrenilen: ${number(vocab.mastered)??"—"}</p></article></div></article>`}
  <section class="report-history"><div class="section-title-row"><h2>Önceki raporlar</h2><button class="button secondary" data-action="generate-previous-report">Önceki dönemi kaydet</button></div>${history.length?history.map(row=>`<button class="card report-history-row" data-report-id="${e(row.id)}"><strong>${row.period_type==="weekly"?"Haftalık":"Aylık"} rapor</strong><span>${e(formatReportRange({start:row.period_start,end:row.period_end}))}</span></button>`).join(""):`<article class="card"><p>Henüz kaydedilmiş önceki rapor yok.</p></article>`}</section></section>`;
}
